from openpyxl import load_workbook

INPUT_PATH = "/app/spreadsheets/1_22-47_input.xlsx"
OUTPUT_PATH = "/app/output/1_22-47_output.xlsx"

SOURCE_COLUMNS = (1, 2, 3)       # A:C -> ITEM, NAME, REF
HELPER_COLUMN = 10               # J
OUTPUT_MIN_ROW = 2
OUTPUT_MAX_ROW = 20
OUTPUT_COLUMNS = (6, 7, 8)       # F:H


def is_blank(value):
    return value is None or (isinstance(value, str) and value.strip() == "")


def normalized(value):
    if value is None:
        return ""
    return str(value).strip()


def is_header_row(item, name, ref):
    return (
        normalized(item).upper() == "ITEM"
        and normalized(name).upper() == "NAME"
        and normalized(ref).upper() == "REF"
    )


def read_unique_source_rows(ws):
    rows = []
    seen_name_ref = set()

    for row_idx in range(1, ws.max_row + 1):
        item, name, ref = [ws.cell(row_idx, col).value for col in SOURCE_COLUMNS]

        if all(is_blank(value) for value in (item, name, ref)):
            continue
        if is_header_row(item, name, ref):
            continue
        if is_blank(name) or is_blank(ref):
            continue

        duplicate_key = (normalized(name).casefold(), normalized(ref).casefold())
        if duplicate_key in seen_name_ref:
            continue

        seen_name_ref.add(duplicate_key)
        rows.append((item, name, ref))

    return rows


def read_helper_names(ws):
    names = []
    seen = set()

    for row_idx in range(1, ws.max_row + 1):
        value = ws.cell(row_idx, HELPER_COLUMN).value
        if is_blank(value):
            continue
        helper_name = normalized(value)
        if helper_name.upper() in {"LIST", "NAME"}:
            continue

        key = helper_name.casefold()
        if key in seen:
            continue

        seen.add(key)
        names.append(helper_name)

    return names


def sort_rows(rows, helper_names):
    if not helper_names:
        return sorted(rows, key=lambda row: normalized(row[1]).casefold())

    sorted_rows = []
    used_indices = set()

    for helper_name in helper_names:
        helper_key = helper_name.casefold()
        for index, row in enumerate(rows):
            if index in used_indices:
                continue
            if normalized(row[1]).casefold() == helper_key:
                sorted_rows.append(row)
                used_indices.add(index)

    for index, row in enumerate(rows):
        if index not in used_indices:
            sorted_rows.append(row)

    return sorted_rows


def write_output(ws, rows):
    for row_idx in range(OUTPUT_MIN_ROW, OUTPUT_MAX_ROW + 1):
        for col_idx in OUTPUT_COLUMNS:
            ws.cell(row_idx, col_idx).value = None

    max_output_rows = OUTPUT_MAX_ROW - OUTPUT_MIN_ROW + 1
    for offset, row_values in enumerate(rows[:max_output_rows]):
        row_idx = OUTPUT_MIN_ROW + offset
        for col_idx, value in zip(OUTPUT_COLUMNS, row_values):
            ws.cell(row_idx, col_idx).value = value


def main():
    workbook = load_workbook(INPUT_PATH)
    worksheet = workbook.active

    source_rows = read_unique_source_rows(worksheet)
    helper_names = read_helper_names(worksheet)
    sorted_rows = sort_rows(source_rows, helper_names)
    write_output(worksheet, sorted_rows)

    workbook.save(OUTPUT_PATH)


if __name__ == "__main__":
    main()
